style.css:
@-moz-document domain("google.com") {
/* ======================================================= */
    /* LOGO SANRIO FIJO EN LA ESQUINA SIN DESAPARECER          */
    /* ======================================================= */
    
    /* 1. Volvemos invisible el gráfico viejo de Google */
    #logo svg,
    .logocont svg,
    .JF1Ygd svg,
    a[href^="https://google.com"] svg,
    a[href="/"] svg,
    .logo img,
    [alt="Google"] {
        opacity: 0 !important;
    }
    
    /* 2. Inyectamos a Hello Kitty por DELANTE de la capa de Google */
    #logo a,
    .logocont a,
    .JF1Ygd a,
    a[href^="https://google.com"],
    .F1hU9b a {
        position: relative !important;
        display: inline-block !important;
        width: 150px !important;  
        height: 50px !important;  
        background: transparent !important; /* Quitamos cualquier color raro de fondo */
    }

    /* El truco mágico: Creamos una capa nueva al frente con la imagen */
    #logo a::before,
    .logocont a::before,
    .JF1Ygd a::before,
    a[href^="https://google.com"]::before,
    .F1hU9b a::before {
        content: "" !important;
        position: absolute !important;
        top: 0 !important;
        left: 0 !important;
        width: 100% !important;
        height: 100% !important;
        background-image: url('https://ibb.co') !important; /* Hello Kitty y amigos */
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: left center !important;
        opacity: 1 !important; /* Forzamos a que sea 100% visible siempre */
        visibility: visible !important;
    }
}
